using System.Reflection;
using System.Xml.Linq;
using Yeetle.App.Resources;

namespace Yeetle.App.Tests;

// Strings.Designer.cs is checked in and regenerated by the IDE; these catch a resx edited elsewhere.
public class StringsTests
{
    private const string ResourcesFolder = "Resources";
    private const string EnglishFile = "Strings.resx";
    private const string FrenchFile = "Strings.fr.resx";

    [Fact]
    public void Every_English_text_has_a_property()
    {
        var properties = typeof(Strings).GetProperties(BindingFlags.Public | BindingFlags.Static)
            .Where(p => p.PropertyType == typeof(string))
            .Select(p => p.Name);

        Assert.Equal(Keys(EnglishFile), properties.Order());
    }

    [Fact]
    public void French_has_the_same_texts_as_English()
    {
        Assert.Equal(Keys(EnglishFile), Keys(FrenchFile));
    }

    private static IEnumerable<string> Keys(string file) =>
        XDocument.Load(Path.Combine(SourceFolder(), ResourcesFolder, file))
            .Root!.Elements("data")
            .Select(e => (string)e.Attribute("name")!)
            .Order();

    // The tests run from bin/; the resx files are read from the source tree.
    private static string SourceFolder()
    {
        for (var folder = new DirectoryInfo(AppContext.BaseDirectory); folder is not null; folder = folder.Parent)
        {
            var app = Path.Combine(folder.FullName, "src", "Yeetle.App");
            if (Directory.Exists(app))
                return app;
        }
        throw new DirectoryNotFoundException("Yeetle.App source folder not found.");
    }
}
